/**
 * Minimal RPC client for driving a real `pi --mode rpc` child process in tests.
 * The client is the trusted confirmation surface: it answers
 * extension_ui_request dialogs over the protocol.
 */

import { type ChildProcessWithoutNullStreams, spawn } from "node:child_process";
import { mkdir, mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { createInterface } from "node:readline";

export const repoRoot = resolve(import.meta.dirname, "../../../..");

export type RpcRecord = { type: string; id?: string; [key: string]: unknown };

export interface RpcPiOptions {
  /** Extra CLI arguments after the isolation flags. */
  args: string[];
  /** Extra environment variables. */
  env?: Record<string, string>;
  /** Optional setup hook receiving the scratch directory before launch. */
  prepare?: (scratch: string) => Promise<void>;
}

export class RpcPi {
  readonly records: RpcRecord[] = [];
  private readonly waiters: Array<{ predicate: (record: RpcRecord) => boolean; resolve: (record: RpcRecord) => void }> =
    [];
  private requestCount = 0;
  readonly stderr: string[] = [];

  constructor(
    readonly child: ChildProcessWithoutNullStreams,
    readonly scratch: string,
  ) {
    createInterface({ input: child.stdout }).on("line", (line) => {
      let record: RpcRecord;
      try {
        record = JSON.parse(line) as RpcRecord;
      } catch {
        return;
      }
      this.records.push(record);
      for (const waiter of this.waiters.splice(0)) {
        if (waiter.predicate(record)) waiter.resolve(record);
        else this.waiters.push(waiter);
      }
    });
    child.stderr.on("data", (chunk: Buffer) => this.stderr.push(chunk.toString("utf8")));
  }

  static async start(options: RpcPiOptions): Promise<RpcPi> {
    const packageDir = join(repoRoot, "node_modules", "@earendil-works", "pi-coding-agent");
    const manifest = JSON.parse(await readFile(join(packageDir, "package.json"), "utf8")) as { bin: { pi: string } };
    const scratch = await mkdtemp(join(tmpdir(), "exa-rpc-pi-"));
    const home = join(scratch, "home");
    const agent = join(home, ".pi", "agent");
    const cwd = join(scratch, "repo");
    await Promise.all([mkdir(cwd), mkdir(agent, { recursive: true })]);
    await options.prepare?.(scratch);
    const env = {
      PATH: process.env.PATH ?? "/usr/bin:/bin",
      HOME: home,
      TMPDIR: scratch,
      PI_CODING_AGENT_DIR: agent,
      PI_OFFLINE: "1",
      PI_SKIP_VERSION_CHECK: "1",
      PI_TELEMETRY: "0",
      ...options.env,
    };
    const args = [
      join(packageDir, manifest.bin.pi),
      "--mode",
      "rpc",
      "--no-extensions",
      "--no-skills",
      "--no-prompt-templates",
      "--no-context-files",
      "--offline",
      "--session-dir",
      join(scratch, "sessions"),
      ...options.args,
    ];
    const child = spawn(process.execPath, args, { cwd, env, stdio: "pipe" });
    return new RpcPi(child, scratch);
  }

  send(record: RpcRecord): string {
    const id = record.id ?? `req-${++this.requestCount}`;
    this.child.stdin.write(`${JSON.stringify({ ...record, id })}\n`);
    return id;
  }

  waitFor(predicate: (record: RpcRecord) => boolean, ms = 15_000): Promise<RpcRecord> {
    const existing = this.records.find(predicate);
    if (existing) return Promise.resolve(existing);
    return new Promise<RpcRecord>((resolveWaiter, reject) => {
      const timer = setTimeout(
        () =>
          reject(
            new Error(
              `RPC wait timed out; last records: ${this.records
                .slice(-6)
                .map((record) => record.type)
                .join(", ")}; stderr: ${this.stderr.join("").slice(-400)}`,
            ),
          ),
        ms,
      );
      this.waiters.push({
        predicate,
        resolve: (record) => {
          clearTimeout(timer);
          resolveWaiter(record);
        },
      });
    });
  }

  settledCount(): number {
    return this.records.filter((record) => record.type === "agent_settled").length;
  }

  /** Send a prompt and wait for the run to settle (or for an extension command to be handled). */
  async prompt(message: string, ms = 15_000): Promise<RpcRecord> {
    const settledBefore = this.settledCount();
    const id = this.send({ type: "prompt", message });
    const response = await this.waitFor((record) => record.type === "response" && record.id === id, ms);
    const data = response.data as { disposition?: string } | undefined;
    if (data?.disposition === "handled") return response;
    await this.waitFor(() => this.settledCount() > settledBefore, ms);
    return response;
  }

  /** Answer the next confirm dialog with the given decision. */
  answerNextConfirm(decision: "confirmed" | "cancelled"): Promise<RpcRecord> {
    const seen = new Set(this.records.filter((record) => record.type === "extension_ui_request").map((r) => r.id));
    const request = this.waitFor(
      (record) => record.type === "extension_ui_request" && record.method === "confirm" && !seen.has(record.id),
    );
    void request.then((dialog) => {
      this.send(
        decision === "confirmed"
          ? { type: "extension_ui_response", id: dialog.id as string, confirmed: true }
          : { type: "extension_ui_response", id: dialog.id as string, cancelled: true },
      );
    });
    return request;
  }

  async entries(): Promise<Array<{ type: string; customType?: string; message?: { role: string; content: unknown } }>> {
    const id = this.send({ type: "get_entries" });
    const response = await this.waitFor((record) => record.type === "response" && record.id === id);
    return (response.data as { entries: Array<{ type: string; customType?: string }> }).entries;
  }

  toolResults(): string[] {
    return this.records.flatMap((record) => {
      const message = record.message as { role?: string; content?: unknown } | undefined;
      return record.type === "message_end" && message?.role === "toolResult" ? [JSON.stringify(message.content)] : [];
    });
  }

  toolCalls(): string[] {
    return this.records.flatMap((record) => {
      const message = record.message as { role?: string; content?: Array<{ type: string; name?: string }> } | undefined;
      return record.type === "message_end" && message?.role === "assistant"
        ? (message.content ?? []).flatMap((block) => (block.type === "toolCall" && block.name ? [block.name] : []))
        : [];
    });
  }

  lastAssistantText(): string {
    const last = this.records
      .filter((record) => record.type === "message_end" && (record.message as { role?: string }).role === "assistant")
      .at(-1);
    return JSON.stringify((last?.message as { content: unknown } | undefined)?.content ?? "");
  }

  async stop(): Promise<void> {
    this.child.stdin.end();
    await new Promise<void>((done) => {
      const timer = setTimeout(() => {
        this.child.kill();
        done();
      }, 3_000);
      this.child.once("exit", () => {
        clearTimeout(timer);
        done();
      });
    });
    await rm(this.scratch, { recursive: true, force: true });
  }
}
EOF
cat > packages/pi-exa/__tests__/guided-smoke.rpc.test.ts <<'EOF'
/**
 * #175 smoke: the complete guided journey on the production pi-exa extension in a
 * real `pi --mode rpc` process, with the real exa-js SDK pointed at a controllable
 * mock Exa HTTP server. Request → clarification/draft → readable proposal →
 * trusted approval over the protocol → immediate saved run ID → continued
 * conversation → background completion → findings/gaps/usage report.
 *
 * This is a mocked interactive smoke over the RPC host surface; it is not an
 * interactive TUI rendering check and performs no paid call.
 */

import { writeFile } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { type MockExaServer, startMockExaServer } from "./fixtures/guided-smoke/mock-exa-server.js";
import { repoRoot, RpcPi } from "./fixtures/rpc-pi.js";

const running: Array<{ stop: () => Promise<void> }> = [];
afterEach(async () => {
  for (const item of running.splice(0)) await item.stop().catch(() => {});
});

async function launch(server: MockExaServer) {
  const pi = await RpcPi.start({
    prepare: async (scratch) => {
      await writeFile(
        join(scratch, "exa.json"),
        JSON.stringify({
          apiKey: "smoke-fixture-key",
          enabledTools: [
            "exa_research_step",
            "exa_research_status",
            "exa_research_summary",
            "exa_research_reset",
            "web_search_exa",
            "web_research_exa",
          ],
        }),
      );
    },
    env: {
      EXA_BASE_URL: server.baseUrl,
      EXA_CONFIG_FILE: join("..", "exa.json"),
    },
    args: [
      "-e",
      join(repoRoot, "packages", "pi-exa", "extensions", "index.ts"),
      "-e",
      join(repoRoot, "packages", "pi-exa", "__tests__", "fixtures", "guided-smoke", "pi-entry.ts"),
      "--exa-enable-cycles",
      "--exa-monitor-interval-ms",
      "50",
      "--provider",
      "exa-smoke",
      "--model",
      "scripted",
      "--thinking",
      "off",
    ],
  });
  running.push(pi);
  return pi;
}

describe("guided background research smoke on the production extension (real pi RPC process, mock Exa endpoints)", () => {
  it("runs the whole journey without slash commands, schemas or hashes typed by the user, and reports after background completion", async () => {
    const server = await startMockExaServer();
    running.push({ stop: () => server.close() });
    const pi = await launch(server);
    // Config paths are resolved relative to the process cwd; point EXA_CONFIG_FILE at the scratch file.
    const dialog = pi.answerNextConfirm("confirmed");
    await pi.prompt("research Laya versus Jev for small structured decisions", 30_000);
    const approval = await dialog;
    expect(approval).toMatchObject({ title: "Approve Exa research spending?", timeout: 600_000 });
    expect(String(approval.message)).toContain("Laya versus Jev");
    expect(String(approval.message)).toContain("estimate $0.10");

    // The assistant drove the cycle itself: start → step → proposal → submit.
    expect(pi.toolCalls()).toEqual(["exa_research_status", "exa_research_step", "exa_research_summary", "web_research_exa"]);
    const results = pi.toolResults();
    expect(results[0]).toContain("Guided draft created without spending");
    expect(results[2]).toContain("Research proposal ");
    expect(results[2]).toContain("Estimated cost: $0.10");
    expect(results[2]).toContain("Nothing was submitted or approved");
    expect(results[3]).toContain("Research started: Exa run smoke_run_1");
    expect(results[3]).toContain("Background monitoring is registered");
    expect(pi.lastAssistantText()).toContain("Research started. I registered background monitoring");
    expect(server.counts()).toMatchObject({ creates: 1, other: 0 });
    expect(server.requests[0]).toMatchObject({ method: "POST", path: "/agent/runs", apiKey: "smoke-fixture-key" });
    expect(server.requests[0].body).toMatchObject({ effort: "medium", metadata: expect.objectContaining({ revision: "1" }) });
    expect(server.runs.get("smoke_run_1")?.status).toBe("running");

    // The user keeps chatting while the mock job is pending and the monitor polls over HTTP.
    await pi.prompt("unrelated chat while it runs");
    expect(pi.lastAssistantText()).toContain("talk about something else");
    await pi.waitFor(() => server.counts().gets >= 1, 10_000);
    expect((await pi.entries()).some((entry) => entry.type === "custom_message")).toBe(false);

    // Remote completion → persisted facts → one completion notice → wakeup → report turn.
    const settledBefore = pi.settledCount();
    server.complete("smoke_run_1");
    await pi.waitFor(
      (record) => record.type === "message_end" && (record.message as { role?: string }).role === "custom",
      15_000,
    );
    await pi.waitFor(() => pi.settledCount() > settledBefore, 15_000);
    const entries = await pi.entries();
    const notices = entries.filter((entry) => entry.type === "custom_message");
    expect(notices).toHaveLength(1);
    expect(notices[0].customType).toBe("exa-research-completion");
    expect(pi.toolCalls().at(-1)).toBe("exa_research_status");
    const report = pi.toolResults().at(-1) ?? "";
    expect(report).toContain('"finalReport"');
    expect(report).toContain('"automaticCriterionSatisfaction":false');
    expect(report).toContain('"billingVerified":false');
    expect(report).toContain("G1");
    expect(pi.lastAssistantText()).toContain("Report: the research finished");
    expect(server.counts()).toMatchObject({ creates: 1, other: 0 });
    // No user prompt was a slash command, no schema or hash was typed by the user.
    const userTexts = pi.records
      .filter((record) => record.type === "message_end" && (record.message as { role?: string }).role === "user")
      .map((record) => JSON.stringify((record.message as { content: unknown }).content));
    expect(userTexts.every((text) => !text.includes('"text":"/'))).toBe(true);
    expect(userTexts.join(" ")).not.toMatch(/[0-9a-f]{16}|draft-07/);
  }, 90_000);

  it("a cancelled dialog in the same journey submits nothing", async () => {
    const server = await startMockExaServer();
    running.push({ stop: () => server.close() });
    const pi = await launch(server);
    const dialog = pi.answerNextConfirm("cancelled");
    await pi.prompt("research Laya versus Jev for small structured decisions", 30_000);
    await dialog;
    expect(pi.toolResults().at(-1)).toContain("APPROVAL_NOT_GRANTED");
    expect(server.counts()).toEqual({ creates: 0, gets: 0, other: 0 });
    expect(pi.lastAssistantText()).toContain("reported a pause");
  }, 60_000);
});
EOF
